  for(const button of document.querySelectorAll('[data-stock-share-mode]'))button.addEventListener('click',()=>{shareMode=button.dataset.stockShareMode;shareKey=crypto.randomUUID();$('stockShareSearch').value='';shareChoices();});
  $('stockShareChangeBranch').addEventListener('click',()=>{shareBranch='';setBranchReview(false);$('stockShareSearch').value='';shareChoices();});
  $('stockShareClear').addEventListener('click',()=>{$('stockShareFilterBranch').value='all';$('stockShareFilterTag').value='';selectedShares.clear();if(!editingShare)shareBranch='';excludedShares.clear();shareKey=crypto.randomUUID();shareChoices();});$('stockShareSearch').addEventListener('input',shareChoices);$('stockShareForm').elements.title.addEventListener('input',()=>shareKey=crypto.randomUUID());
