  $('stockShareForm').addEventListener('submit',async e=>{e.preventDefault();const submit=e.submitter;if(submit.disabled)return;submit.disabled=true;try{const body={action:editingShare?'share_exclusions':'share',id:editingShare?.id||0,title:e.target.elements.title.value,operation_key:shareKey,...(shareMode==='branch'?{branch_id:shareBranch,excluded_ids:JSON.stringify([...excludedShares])}:{pallet_ids:JSON.stringify([...selectedShares])})};const saved=await api(body);if(left)return;await refresh();if(editingShare){$('stockShareDialog').close();$('stockSharesStatus').textContent='Palets compartidos actualizados.';}else result(saved.share);}catch(err){$('stockShareStatus').textContent=err.message;}finally{submit.disabled=false;}});
